/**
 * Crisis-input normalisation for MATCHING ONLY (WO#391, Gem 3 ruling of
 * 27 Sep 2026, CRITICAL).
 *
 * The detector matched keywords as plain substrings of the lower-cased input,
 * so trivially obfuscated input ("kill-myself", "sui<U+200B>cide", "k1ll myself",
 * "killmyself", "my-husband-hits-me") missed the crisis gate. These helpers
 * produce the strings the detector matches against. They NEVER change the
 * text that is returned, stored or logged: callers keep the original input.
 *
 * Steps (Gem 3 numbering, plus the Architect addendum 6 and 7):
 *   1  strip zero-width characters (U+200B, U+200C, U+200D, U+2060, U+FEFF)
 *   2  hyphens, underscores, dots and repeated punctuation -> single space
 *   6  Unicode dashes (en, em, minus, ...) and Unicode spaces (NBSP, narrow
 *      NBSP, ...) and whitespace runs -> single space (part of step 2 here)
 *   3  leetspeak (1->i or l, !->i, 3->e 0->o @->a 4->a 5->s $->s 7->t), ENGLISH
 *      terms only. "1" is tried as both i and l (WO#391 addendum (b), (c))
 *   4  letter-spaced runs ("k i l l") collapsed, Latin letters/digits only
 *   5  3+ repeated letters collapsed to 1 AND to 2, both tested, ENGLISH only
 *   7  no-separator forms: a keyword with its spaces removed, matched only
 *      where it starts and ends on a token boundary of the input
 *   B  word boundaries for ENGLISH keywords (WO#391 addendum (d)): a match
 *      must start at a word boundary, or right after a glued pronoun
 *      ("iraped", as in step 7). Only the keywords the detector marks
 *      end-bounded ("self harm", the "hits me" family) must also end at one,
 *      or in an inflectional suffix (-ing, -ed, -s, -er), or a repeated final
 *      letter. So "self-harming" and "self-harmed" match "self harm";
 *      "self-harmony" and "the hits media" do not; "kill myselfnow" does.
 *
 * Arabic-script text (ar, ur, fa, pa) gets steps 1 and 2 only. Steps 3 to 5
 * and 7 are NOT applied to it until Gem 2 rules on false-positive risk (open
 * item, WO#391 SG report). Bengali script gets steps 1 and 2 only as well:
 * step 4's letter class and steps 3, 5 and 7 are ASCII-only by construction.
 *
 * Pure functions, no imports, so the file syncs to mcp-server unchanged.
 */

/** Step 1. Zero-width space, ZWNJ, ZWJ, word joiner, BOM / ZW no-break space. */
const ZERO_WIDTH = /[\u200B\u200C\u200D\u2060\uFEFF]/g

/** Step 6. Unicode spaces that `\s` may or may not cover, made explicit. */
const UNICODE_SPACE = /[\u00A0\u1680\u2000-\u200A\u202F\u205F\u3000]/g

/** Step 2 + 6. Hyphen family (ASCII hyphen-minus, U+2010..U+2015 incl. en and
 *  em dash, minus sign, small/fullwidth hyphen-minus), underscore, dot and the
 *  one-dot leader / ellipsis, in any run length. Also "#": a hashtag
 *  ("#iwanttodie") is a word, so its "#" is a separator (Architect review of
 *  2e02e5f: the start boundary must not lose hashtag forms that hit on main). */
const SEPARATOR_RUN = /[\-\u2010-\u2015\u2212\uFE58\uFE63\uFF0D_.\u2024\u2026#]+/g

/** Step 2. Any run of 2+ punctuation or symbol characters. */
const PUNCT_RUN = /[\p{P}\p{S}]{2,}/gu

export function stripZeroWidth(s: string): string {
  return s.replace(ZERO_WIDTH, '')
}

/** Steps 1, 2 and 6, in order. Safe for every script. */
export function normaliseSeparators(s: string): string {
  return stripZeroWidth(s)
    .replace(UNICODE_SPACE, ' ')
    .replace(SEPARATOR_RUN, ' ')
    .replace(PUNCT_RUN, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

/** Step 4. A run of 3+ single-character tokens ("k i l l", "s u i c i d e")
 *  becomes one token. Letters a-z, digits and the leet symbols only, so
 *  Arabic and Bengali text is never touched. */
const SINGLE = /^[a-z0-9@$]$/
export function collapseLetterSpacing(s: string): string {
  const tokens = s.split(' ')
  const out: string[] = []
  for (let i = 0; i < tokens.length; ) {
    let j = i
    while (j < tokens.length && SINGLE.test(tokens[j])) j++
    if (j - i >= 3) {
      out.push(tokens.slice(i, j).join(''))
      i = j
    } else {
      out.push(tokens[i])
      i++
    }
  }
  return out.join(' ')
}

/** Step 3. Gem 3's map, plus "!" -> i (addendum (b)). "1" is ambiguous
 *  (i or l, addendum (c)); unLeet takes which one to use. */
const LEET: Record<string, string> = { '!': 'i', '3': 'e', '0': 'o', '@': 'a', '4': 'a', '5': 's', '$': 's', '7': 't' }
export function unLeet(s: string, one: 'i' | 'l' = 'i'): string {
  return s.replace(/[1!30@45$7]/g, (c) => (c === '1' ? one : LEET[c]))
}

/**
 * Every leet reading of `s`: each "1" as i or as l. Up to 6 ones gives every
 * combination ("k1ll myse1f" needs l then l, "su1c1d3" i then i, a mix is
 * covered too); more than 6 gives the two uniform readings only, so the
 * variant count stays bounded (at most 64).
 */
const MAX_ONES_FOR_COMBINATIONS = 6
export function leetVariants(s: string): string[] {
  const ones = [...s].filter((c) => c === '1').length
  if (ones === 0) return [unLeet(s)]
  if (ones > MAX_ONES_FOR_COMBINATIONS) return [unLeet(s, 'i'), unLeet(s, 'l')]
  const out: string[] = []
  for (let mask = 0; mask < 1 << ones; mask++) {
    let k = 0
    const withOnes = s.replace(/1/g, () => ((mask >> k++) & 1 ? 'l' : 'i'))
    out.push(unLeet(withOnes))
  }
  return out
}

/** Step 5. 3+ repeats of a letter a-z, collapsed to one and to two. */
export function collapseRepeats(s: string): [string, string] {
  return [s.replace(/([a-z])\1{2,}/g, '$1'), s.replace(/([a-z])\1{2,}/g, '$1$1')]
}

/**
 * The strings an ENGLISH keyword is matched against: the base, and the
 * leet / repeat-collapsed variants of it (steps 3 and 5), de-duplicated.
 */
export function englishVariants(base: string): string[] {
  const out = new Set<string>([base, ...collapseRepeats(base)])
  for (const leet of leetVariants(base)) {
    out.add(leet)
    for (const r of collapseRepeats(leet)) out.add(r)
  }
  return [...out]
}

/**
 * Step B. True if the match at `i` is preceded by one of SQUASH_PREFIXES
 * that itself starts a word: "iraped", "ikms", "myhusband hits me". Mirrors
 * step 7, so a pronoun glued to a keyword never costs a hit that main had.
 * "draped" and "skill myself" still fail ("d" and "s" are not pronouns).
 */
function afterGluedPronoun(haystack: string, i: number): boolean {
  for (const p of SQUASH_PREFIXES) {
    const at = i - p.length
    if (at >= 0 && haystack.startsWith(p, at) && (at === 0 || !WORD_CHAR.test(haystack[at - 1]))) return true
  }
  return false
}

/** Step B. A word character, in any script. */
const WORD_CHAR = /[\p{L}\p{N}]/u
/** Step B. What may follow an English keyword inside the same word. */
const INFLECTION = /^(?:ing|ed|s|er)(?![\p{L}\p{N}])/u

/**
 * Step B. `needle` occurs in `haystack` starting at a word boundary and
 * ending at one (a repeated final letter allowed), or ending in an
 * inflectional suffix and then a boundary.
 * `openEnd` keywords (every English keyword but the end-bounded few) may run
 * on into any letters after the match; only the start is bounded.
 * `suppressAfter`, when given, skips an occurrence whose continuation matches
 * it (the Gem 3 "kms" distance rule).
 */
export function boundedIncludes(haystack: string, needle: string, openEnd = false, suppressAfter?: RegExp): boolean {
  for (let i = haystack.indexOf(needle); i >= 0; i = haystack.indexOf(needle, i + 1)) {
    if (i > 0 && WORD_CHAR.test(haystack[i - 1]) && !afterGluedPronoun(haystack, i)) continue
    // A repeated final letter is emphasis, not a new word ("kill myselff",
    // "want to diee"); 3+ repeats are also collapsed by step 5.
    // Both ends are tried, so "dieed" still reads as "die" + "ed".
    const plain = i + needle.length
    let repeated = plain
    const last = needle[needle.length - 1]
    while (haystack[repeated] === last) repeated++
    for (const end of plain === repeated ? [plain] : [plain, repeated]) {
      const rest = haystack.slice(end)
      // A keyword-specific context that makes THIS occurrence benign
      // ("kms walk"). Other occurrences in the input are still checked.
      if (suppressAfter && suppressAfter.test(rest)) continue
      if (openEnd || !rest || !WORD_CHAR.test(rest[0]) || INFLECTION.test(rest)) return true
    }
  }
  return false
}

/**
 * Step 7 prefixes. A no-separator phrase usually arrives glued to the pronoun
 * before it ("hebeatsme", "myhusbandhitsme", "iwanttodie"). The match may
 * start after one of these at the start of a token, and nowhere else inside
 * a token, so "skillmyself" still does not match "kill myself".
 */
const SQUASH_PREFIXES: readonly string[] = ['i', 'im', 'my', 'me', 'he', 'she', 'we', 'they', 'his', 'her', 'our', 'your', 'u']

/**
 * Step 7. True if `keyword` with its spaces removed occurs in `input` with its
 * spaces removed, starting at the start of an input token (or right after a
 * SQUASH_PREFIXES pronoun there) and ending at the end of one. "killmyself",
 * "kill myself" typed as "killmy self", "k i l l m y s e l f" (after step 4)
 * and "myhusbandhitsme" match; "skillmyself" does not.
 */
export function matchesSquashed(input: string, keyword: string): boolean {
  const squashedKw = keyword.replace(/ /g, '')
  if (!squashedKw) return false
  const starts = new Set<number>()
  const ends = new Set<number>()
  let squashed = ''
  for (const t of input.split(' ')) {
    if (!t) continue
    starts.add(squashed.length)
    for (const p of SQUASH_PREFIXES) if (t.length > p.length && t.startsWith(p)) starts.add(squashed.length + p.length)
    squashed += t
    ends.add(squashed.length)
  }
  for (let i = squashed.indexOf(squashedKw); i >= 0; i = squashed.indexOf(squashedKw, i + 1)) {
    if (starts.has(i) && ends.has(i + squashedKw.length)) return true
  }
  return false
}

/** Keywords step 7 applies to: Latin script (a-z after folding), squashed
 *  length 6 or more, so short entries ("kms", "kdrt") cannot collide. */
export function isSquashable(keyword: string): boolean {
  return /^[a-z0-9 ]+$/.test(keyword) && keyword.replace(/ /g, '').length >= 6
}
